from fastapi import FastAPI, Header
from fastapi.testclient import TestClient
import pytest

app = FastAPI()

@app.get("/")
async def read_root(x_token: str = Header()):
    return {"x_token": x_token}

client = TestClient(app)

def test_header_underscore_not_accepted_by_default():
    # By default convert_underscores=True. 
    # It should accept 'x-token' and NOT 'x_token'.

    # Should work with hyphen
    response = client.get("/", headers={"x-token": "foo"})
    assert response.status_code == 200
    assert response.json() == {"x_token": "foo"}

    # Should NOT work with underscore (should return 422 Unprocessable Entity)
    response = client.get("/", headers={"x_token": "bar"})
    assert response.status_code == 422

@app.get("/explicit")
async def read_explicit(x_token: str = Header(convert_underscores=False)):
    return {"x_token": x_token}

def test_header_underscore_accepted_when_convert_underscores_false():
    # When convert_underscores=False, it should accept 'x_token'
    response = client.get("/explicit", headers={"x_token": "bar"})
    assert response.status_code == 200
    assert response.json() == {"x_token": "bar"}

